import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).strip();
        long dx = 0, dy = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'R') dx++;
            else if (c == 'L') dx--;
            else if (c == 'U') dy++;
            else if (c == 'D') dy--;
        }
        // Only the Manhattan distance to the endpoint must stay; every other move can go.
        System.out.println(s.length() - Math.abs(dx) - Math.abs(dy));
    }
}

package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := bytes.TrimSpace(raw)
	dx, dy := 0, 0
	for _, c := range s {
		switch c {
		case 'R':
			dx++
		case 'L':
			dx--
		case 'U':
			dy++
		case 'D':
			dy--
		}
	}
	// Only the Manhattan distance to the endpoint must stay; every other move can go.
	fmt.Println(len(s) - abs(dx) - abs(dy))
}
